def job_page(token: str) -> HTMLResponse:
    job = _job(token)
    if not job:
        raise HTTPException(404)
    e = html.escape
    return _page(f"PaperCI - {job['title'] or 'verification'}", f"""
<div class=wrap><div style="padding-top:18px"><span class="pill {e(job['status'])}" id=pill>{e(job['status'])}</span>
<span class=muted id=meta style="margin-left:8px"></span>
<h1 style="font-size:30px;margin:10px 0 0" id=ttl>{e(job['title'] or job['input'])}</h1>
<div class=muted>Private link for {e(job['email'])} · keep it to come back later</div></div>
<div class=jobgrid><div><div class=box><h4>Progress</h4><div id=steps></div></div>
<div class=box><h4>Connections the agent made</h4><div class=chips id=conns><span class=muted>waiting...</span></div>
<div class=muted style="margin-top:10px">Builds can only reach an allowlist of code and data hosts. Verification runs with no network at all.</div></div></div>
<div><div class=box style="display:flex;gap:28px"><div><div class=big id=cl>-</div><div class=muted>claims sealed (values hidden from the agent)</div></div>
<div><div class=big id=el>0:00</div><div class=muted>elapsed</div></div><div><div class=big id=tn>0</div><div class=muted>agent actions</div></div></div>
<div class=box><h4>Agent activity</h4><div class=term id=feed><span class=t>waiting for the sandbox...</span></div></div>
<div id=done></div></div></div>
<div id=rev class=wrap style="padding:0 0 60px"></div></div>
<script>
const G={{'+':'ok','!':'warn','x':'fail','~':'heal','>':'','.':'','=':''}};
function esc(s){{return s.replace(/[&<>]/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;'}}[c]))}}
let shown=false;
async function tick(){{const r=await fetch('/api/job/{token}');const j=await r.json();
document.getElementById('pill').className='pill '+j.status;document.getElementById('pill').textContent=j.status;
document.getElementById('meta').textContent=j.status=='queued'?(j.queued_ahead+' verification(s) ahead of you'):'';
if(j.title)document.getElementById('ttl').textContent=j.title;
document.getElementById('steps').innerHTML=j.steps.map(s=>`<div class="st ${{s.state}}"><div class=dot>${{s.state=='ok'?'&#10003;':s.state=='fail'?'!':''}}</div><div><div class=n>${{s.name}}</div><div class=w>${{s.why}}</div>${{s.detail?`<div class=d>${{esc(s.detail)}}</div>`:''}}</div></div>`).join('');
if(j.connections.length)document.getElementById('conns').innerHTML=j.connections.map(c=>`<span class="chip ${{c.state}}">${{c.state=='blocked'?'&#10007; ':c.state=='off'?'':'&#10003; '}}${{esc(c.host)}}</span>`).join('');
document.getElementById('cl').textContent=j.claims_sealed??'-';const m=Math.floor(j.elapsed/60),s=j.elapsed%60;document.getElementById('el').textContent=m+':'+String(s).padStart(2,'0');
document.getElementById('tn').textContent=j.feed.length;
const f=document.getElementById('feed');if(j.feed.length){{const at=f.scrollTop+f.clientHeight>=f.scrollHeight-20;
f.innerHTML=j.feed.map(x=>`<div><span class=t>${{x.t}}</span><span class="g ${{G[x.g]||''}}">${{x.g}}</span>${{esc(x.text)}}</div>`).join('');if(at)f.scrollTop=f.scrollHeight;}}
if(j.status=='failed')document.getElementById('done').innerHTML=`<div class=err>The run stopped: ${{esc(j.error||'')}}</div>`;
