"""Count occurrences of the real secret values (from .env) in files, without printing them.

  python scripts/secret_scan.py <file-or-dir> [...]
  python scripts/secret_scan.py --git        # working tree + full git history
Exit code 1 if any secret is found."""
import os
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
names = ("NEATLOGS_API_KEY", "LITELLM_API_KEY", "CRUSTDATA_API_KEY")
secrets = {}
for line in (ROOT / ".env").read_text().splitlines():
    k, _, v = line.partition("=")
    if k in names and len(v) >= 12:
        secrets[k] = v.encode()
try:
    tok = subprocess.run(["gh", "auth", "token"], capture_output=True, timeout=15).stdout.strip()
    if len(tok) > 12:
        secrets["GH_TOKEN"] = tok
except Exception:
    pass


def scan_bytes(label: str, data: bytes) -> int:
    hits = 0
    for k, v in secrets.items():
        n = data.count(v)
        if n:
            print(f"FOUND {k} x{n} in {label}")
            hits += n
    return hits


total = 0
if sys.argv[1:] == ["--git"]:
    tracked = subprocess.run(["git", "ls-files", "-z"], cwd=ROOT, capture_output=True).stdout.split(b"\0")
    for f in tracked:
        if f:
            p = ROOT / f.decode()
            if p.is_file():
                total += scan_bytes(f"worktree:{f.decode()}", p.read_bytes())
    revs = subprocess.run(["git", "rev-list", "--all"], cwd=ROOT, capture_output=True, text=True).stdout.split()
    for rev in revs:
        diff = subprocess.run(["git", "show", "--format=%B", "-p", rev], cwd=ROOT, capture_output=True).stdout
        total += scan_bytes(f"commit:{rev[:10]}", diff)
    refs = subprocess.run(["git", "for-each-ref", "--format=%(objectname)"], cwd=ROOT, capture_output=True, text=True).stdout.split()
    objs = subprocess.run(["git", "rev-list", "--objects", "--all"], cwd=ROOT, capture_output=True, text=True).stdout.split("\n")
    for line in objs:
        sha = line.split(" ")[0]
        if sha:
            blob = subprocess.run(["git", "cat-file", "-p", sha], cwd=ROOT, capture_output=True).stdout
            total += scan_bytes(f"object:{sha[:10]}", blob)
    print(f"scanned {len(tracked)} tracked files, {len(revs)} commits, {len(objs)} objects")
else:
    for arg in sys.argv[1:]:
        p = Path(arg)
        files = [p] if p.is_file() else [x for x in p.rglob("*") if x.is_file()]
        for f in files:
            total += scan_bytes(str(f), f.read_bytes())
print("secrets checked:", sorted(secrets), "hits:", total)
sys.exit(1 if total else 0)

def classify(output: str, exit_code: int, cmd: str = "") -> str | None:
    if exit_code == 0:
        # `cmd | tail` returns tail's exit code; look for unmistakable errors anyway,
        # but never in commands that merely display files (source code mentions errors).
        if _READ_ONLY.match(cmd) or not _MASKED.search(output[-6000:]):
            return None
        for cat, rx in _COMPILED:
            if rx.search(output[-6000:]):
                return cat
        return None
    if exit_code == 124:
        return "timeout"
    if exit_code == 137:
        return "oom"
    tail = output[-6000:]
    for cat, rx in _COMPILED:
        if rx.search(tail):
            return cat
    return "nonzero_exit"


def load_playbook() -> Playbook:
    if PLAYBOOK_PATH.exists():
        return Playbook.model_validate_json(PLAYBOOK_PATH.read_text(encoding="utf-8"))
    return Playbook()


def save_playbook(pb: Playbook) -> None:
    PLAYBOOK_PATH.write_text(pb.model_dump_json(indent=2), encoding="utf-8")


class Recovery:
    """Per-build recovery state: matches playbook rules and breaks stalls."""

    def __init__(self, variant: str):
        self.variant = variant
        self.playbook = load_playbook() if variant != "v1" else Playbook()
        self._rx = []
        for r in self.playbook.rules:
            try:
                self._rx.append((r, re.compile(r.pattern, re.I)))
            except re.error:
                continue
        self.counts: Counter[str] = Counter()
        self.used_rules: list[str] = []

    @property
    def enabled(self) -> bool:
        return self.variant != "v1"

    def guidance(self, category: str | None, output: str) -> str:
        if not category or not self.enabled:
            return ""
        self.counts[category] += 1
        parts = []
        for rule, rx in self._rx:
            if (rule.category == category or rx.search(output[-6000:])) and rule.rule_id not in self.used_rules[-3:]:
                parts.append(f"[playbook {rule.rule_id}] {rule.advice}")
                self.used_rules.append(rule.rule_id)
                if len(parts) >= 2:
                    break
        if self.counts[category] >= 3:
            parts.append(f"[stall breaker] '{category}' has now happened {self.counts[category]} times. "
                         "Do not repeat the same fix. Change strategy (different entry point, smaller "
                         "config, replace the failing component) or call give_up with a precise reason.")
        return ("\n\nRECOVERY GUIDANCE (failure class: " + category + ")\n" + "\n".join(parts)) if parts else ""

    def prompt_prior(self) -> str:
        """Short list of learned lessons, shown up front in v2."""
        if not self.enabled or not self.playbook.rules:
            return ""
        lines = [f"- ({r.category}) {r.advice}" for r in self.playbook.rules[:12]]
        return ("\nLESSONS LEARNED FROM PREVIOUS PAPERS (playbook generation "
                f"{self.playbook.generation}):\n" + "\n".join(lines) + "\n")


def snippet_for(output: str, category: str) -> str:
    for cat, rx in _COMPILED:
        if cat == category:
            m = rx.search(output)
            if m:
                s = max(0, m.start() - 300)
                return output[s:m.end() + 300]
    return output[-600:]


def dump_counts(rows: list[dict]) -> str:
    return json.dumps(Counter(r["category"] for r in rows).most_common(), indent=0)


